-- ============================================================
--  SECTION 1 — 001-init-inspections.sql
-- ============================================================

create extension if not exists "pgcrypto";

-- ------------------------------------------------------------
-- Division identity (exactly one row per database)
-- ------------------------------------------------------------
create table division_profile (
  id              boolean primary key default true check (id),
  code            text not null,              -- 'MVS'
  name            text not null,              -- 'ACTOM MV Switchgear'
  legal_name      text not null default 'A division of ACTOM (Pty) Ltd',
  hold_points     boolean not null default false,
  fy_start_month  smallint not null default 7,
  created_at      timestamptz not null default now()
);

-- ------------------------------------------------------------
-- People and access
-- ------------------------------------------------------------
create type user_role as enum
  ('inspector','supervisor','quality_engineer','quality_manager','planner','sysadmin','readonly');

create table departments (
  id          smallserial primary key,
  name        text not null unique,
  stage_id    smallint,                        -- fk added after stages
  active      boolean not null default true,
  sort_order  smallint not null default 0
);

create table profiles (
  id            uuid primary key references auth.users(id) on delete cascade,
  entra_oid     text unique,
  full_name     text not null,
  email         text not null,
  role          user_role not null default 'inspector',
  department_id smallint references departments(id),
  active        boolean not null default false, -- new users inactive until activated
  created_at    timestamptz not null default now()
);

create table competencies (
  id            serial primary key,
  profile_id    uuid not null references profiles(id) on delete cascade,
  skill         text not null,
  level         smallint not null check (level between 0 and 3),
  valid_from    date,
  valid_to      date,
  unique (profile_id, skill)
);

-- ------------------------------------------------------------
-- Reference lists (administrator-maintained)
-- ------------------------------------------------------------
create table manufacturing_stages (
  id         smallserial primary key,
  name       text not null unique,
  sort_order smallint not null default 0,
  active     boolean not null default true
);
alter table departments
  add constraint departments_stage_fk foreign key (stage_id) references manufacturing_stages(id);

create table product_families (
  id      smallserial primary key,
  name    text not null unique,
  active  boolean not null default true
);

create table defect_codes (
  id          smallserial primary key,
  code        text not null unique,            -- immutable
  description text not null,                   -- editable
  default_department_id smallint references departments(id),
  active      boolean not null default true
);

create table equipment (
  id           serial primary key,
  asset_no     text not null unique,
  name         text not null,
  category     text not null,
  location     text,
  interval_months smallint,
  last_calibrated date,
  next_due     date,
  status       text not null default 'calibrated'
               check (status in ('calibrated','due','overdue','out_of_service','repair')),
  active       boolean not null default true
);

-- ------------------------------------------------------------
-- Inspection form templates (built in the form designer)
-- ------------------------------------------------------------
create type template_status as enum ('draft','in_review','published','superseded');

create table inspection_templates (
  id            uuid primary key default gen_random_uuid(),
  code          text not null unique,          -- IT-ASM-04
  name          text not null,
  stage_id      smallint not null references manufacturing_stages(id),
  family_id     smallint references product_families(id),   -- null = all families
  min_competency smallint not null default 2 check (min_competency between 1 and 3),
  fail_mode     text not null default 'record'
                check (fail_mode in ('record','hold','quarantine')),
  created_by    uuid references profiles(id),
  created_at    timestamptz not null default now()
);

create table template_revisions (
  id            uuid primary key default gen_random_uuid(),
  template_id   uuid not null references inspection_templates(id) on delete cascade,
  rev           smallint not null,
  status        template_status not null default 'draft',
  definition    jsonb not null,                -- sections + fields, as built in the designer
  created_by    uuid not null references profiles(id),
  approved_by   uuid references profiles(id),  -- must differ from created_by
  effective_from date,
  created_at    timestamptz not null default now(),
  unique (template_id, rev),
  constraint approver_not_author check (approved_by is null or approved_by <> created_by)
);
create unique index one_published_rev
  on template_revisions (template_id) where status = 'published';

-- ------------------------------------------------------------
-- Requirements matrix (family x stage) — configured by admin
-- ------------------------------------------------------------
create table inspection_requirements (
  id            serial primary key,
  family_id     smallint not null references product_families(id) on delete cascade,
  stage_id      smallint not null references manufacturing_stages(id) on delete cascade,
  template_id   uuid references inspection_templates(id),
  level         text not null default 'required'
                check (level in ('hold','required','optional','na')),
  sampling      text not null default 'full'
                check (sampling in ('full','first_off','sample_pct','per_shift','per_delivery')),
  sample_pct    smallint,
  min_competency smallint check (min_competency between 1 and 3),
  updated_by    uuid references profiles(id),
  updated_at    timestamptz not null default now(),
  unique (family_id, stage_id)
);

-- ------------------------------------------------------------
-- Work
-- ------------------------------------------------------------
create table projects (
  id          serial primary key,
  code        text not null unique,            -- P-26118
  name        text not null,
  customer    text,
  family_id   smallint references product_families(id),
  active      boolean not null default true
);

create table works_orders (
  id          serial primary key,
  code        text not null unique,            -- WO-44812
  project_id  int not null references projects(id),
  description text,
  qty         int not null default 1,
  status      text not null default 'open'
              check (status in ('open','held','closed')),
  released_at timestamptz
);

-- ------------------------------------------------------------
-- Inspections
-- ------------------------------------------------------------
create type inspection_status as enum
  ('scheduled','in_progress','completed','cancelled');

create table inspections (
  id             uuid primary key default gen_random_uuid(),
  ref            text not null unique,          -- INS-26-1191
  template_rev_id uuid not null references template_revisions(id),  -- version-locked
  stage_id       smallint not null references manufacturing_stages(id),
  project_id     int references projects(id),
  works_order_id int references works_orders(id),
  unit_ref       text,                          -- panel serial / batch
  assigned_to    uuid references profiles(id),
  department_id  smallint references departments(id),
  planned_date   date,
  status         inspection_status not null default 'scheduled',
  result         text check (result in ('pass','fail')),
  generated_from text not null default 'works_order',
  started_at     timestamptz,
  completed_at   timestamptz,
  signed_by      uuid references profiles(id),
  signed_at      timestamptz,
  signature_hash text,                          -- hash of payload at signature
  amends_id      uuid references inspections(id), -- correction chain
  created_at     timestamptz not null default now()
);
create index inspections_open_idx on inspections (status, planned_date);
create index inspections_assigned_idx on inspections (assigned_to) where status <> 'completed';

create table inspection_results (
  id            uuid primary key default gen_random_uuid(),
  inspection_id uuid not null references inspections(id) on delete cascade,
  field_id      text not null,                  -- field id from the template definition
  label         text not null,                  -- denormalised: survives template edits
  value_text    text,
  value_num     numeric,
  outcome       text check (outcome in ('pass','fail','na')),
  equipment_id  int references equipment(id),
  comment       text,
  recorded_at   timestamptz not null default now(),
  unique (inspection_id, field_id)
);

create table attachments (
  id            uuid primary key default gen_random_uuid(),
  inspection_id uuid references inspections(id) on delete cascade,
  result_id     uuid references inspection_results(id) on delete cascade,
  storage_path  text not null,
  kind          text not null default 'photo',
  uploaded_by   uuid not null references profiles(id),
  uploaded_at   timestamptz not null default now()
);

-- Failed checks: the Phase 1 home for a failure. In Phase 2 these
-- become the source records for NCRs without any data migration.
create table failed_checks (
  id            uuid primary key default gen_random_uuid(),
  ref           text not null unique,           -- FC-26-0212
  inspection_id uuid not null references inspections(id) on delete cascade,
  result_id     uuid not null references inspection_results(id) on delete cascade,
  defect_code_id smallint references defect_codes(id),
  is_hold       boolean not null default false,
  disposition   text check (disposition in
                ('awaiting','rework_reinspect','accept_concession','quarantine','scrap')),
  disposition_by uuid references profiles(id),
  disposition_at timestamptz,
  reason        text,
  ncr_id        uuid,                            -- populated in Phase 2
  created_at    timestamptz not null default now()
);

-- ------------------------------------------------------------
-- Audit trail — append only, no update or delete for anyone
-- ------------------------------------------------------------
create table audit_trail (
  id          bigserial primary key,
  at          timestamptz not null default now(),
  actor       uuid,
  actor_name  text,
  action      text not null,
  entity      text not null,
  entity_id   text,
  detail      jsonb
);
create index audit_trail_at_idx on audit_trail (at desc);

-- ------------------------------------------------------------
-- Reference numbering — sequence table + advisory lock.
-- Never max(id)+1: two inspectors submitting at once must not collide.
-- ------------------------------------------------------------
create table ref_sequences (
  prefix   text primary key,
  period   text not null,
  last_val int  not null default 0
);

create or replace function next_ref(p_prefix text, p_width int default 4)
returns text language plpgsql as $$
declare v_period text; v_next int;
begin
  v_period := to_char(now(), 'YY');
  perform pg_advisory_xact_lock(hashtext(p_prefix));
  insert into ref_sequences (prefix, period, last_val)
    values (p_prefix, v_period, 0)
    on conflict (prefix) do nothing;
  update ref_sequences
     set last_val = case when period = v_period then last_val + 1 else 1 end,
         period   = v_period
   where prefix = p_prefix
  returning last_val into v_next;
  return p_prefix || '-' || v_period || '-' || lpad(v_next::text, p_width, '0');
end $$;

-- ------------------------------------------------------------
-- Helper functions used by every policy
-- ------------------------------------------------------------
create or replace function me() returns profiles
language sql stable security definer set search_path = public as $$
  select * from profiles where id = auth.uid()
$$;

create or replace function has_role(variadic roles user_role[])
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from profiles
    where id = auth.uid() and active and role = any(roles)
  )
$$;

create or replace function my_department() returns smallint
language sql stable security definer set search_path = public as $$
  select department_id from profiles where id = auth.uid()
$$;

-- ------------------------------------------------------------
-- Controls enforced in the database, not the browser.
-- These are the rules an auditor will test.
-- ------------------------------------------------------------

-- 1. A signed inspection cannot be edited. Corrections create a new record.
create or replace function inspection_immutable_after_signature()
returns trigger language plpgsql as $$
begin
  if old.signed_at is not null then
    raise exception 'INS_SIGNED: % is signed and cannot be edited. Create an amendment.', old.ref;
  end if;
  return new;
end $$;
create trigger trg_inspection_lock before update on inspections
  for each row execute function inspection_immutable_after_signature();

create or replace function result_immutable_after_signature()
returns trigger language plpgsql as $$
declare v_signed timestamptz;
begin
  select signed_at into v_signed from inspections
   where id = coalesce(new.inspection_id, old.inspection_id);
  if v_signed is not null then
    raise exception 'INS_SIGNED: inspection is signed; results are read-only';
  end if;
  return coalesce(new, old);
end $$;
create trigger trg_result_lock before insert or update or delete on inspection_results
  for each row execute function result_immutable_after_signature();

-- 2. An instrument that is out of calibration cannot be used on a result.
create or replace function block_uncalibrated_equipment()
returns trigger language plpgsql as $$
declare v_status text;
begin
  if new.equipment_id is not null then
    select status into v_status from equipment where id = new.equipment_id;
    if v_status in ('overdue','out_of_service') then
      raise exception 'EQUIP_BLOCKED: equipment is % and cannot be used to record a result', v_status;
    end if;
  end if;
  return new;
end $$;
create trigger trg_equipment_block before insert or update on inspection_results
  for each row execute function block_uncalibrated_equipment();

-- 3. Signing requires the competency the template demands.
create or replace function enforce_signature_competency()
returns trigger language plpgsql as $$
declare v_min smallint; v_have smallint;
begin
  if new.signed_at is not null and old.signed_at is null then
    select t.min_competency into v_min
      from template_revisions tr
      join inspection_templates t on t.id = tr.template_id
     where tr.id = new.template_rev_id;
    select coalesce(max(level),0) into v_have
      from competencies
     where profile_id = new.signed_by
       and (valid_to is null or valid_to >= current_date);
    if v_have < v_min then
      raise exception 'COMPETENCY: signer holds level %, template requires level %', v_have, v_min;
    end if;
  end if;
  return new;
end $$;
create trigger trg_signature_competency before update on inspections
  for each row execute function enforce_signature_competency();

-- 4. Every consequential change is written to the audit trail.
create or replace function write_audit()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_name text;
begin
  select full_name into v_name from profiles where id = auth.uid();
  insert into audit_trail (actor, actor_name, action, entity, entity_id, detail)
  values (auth.uid(), coalesce(v_name,'system'), lower(tg_op), tg_table_name,
          coalesce(new.id::text, old.id::text),
          case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end);
  return coalesce(new, old);
end $$;
create trigger trg_audit_inspections after insert or update on inspections
  for each row execute function write_audit();
create trigger trg_audit_templates after insert or update on template_revisions
  for each row execute function write_audit();
create trigger trg_audit_requirements after insert or update or delete on inspection_requirements
  for each row execute function write_audit();
create trigger trg_audit_failed after insert or update on failed_checks
  for each row execute function write_audit();

-- ------------------------------------------------------------
-- Row level security
-- ------------------------------------------------------------
alter table division_profile        enable row level security;
alter table departments             enable row level security;
alter table profiles                enable row level security;
alter table competencies            enable row level security;
alter table manufacturing_stages    enable row level security;
alter table product_families        enable row level security;
alter table defect_codes            enable row level security;
alter table equipment               enable row level security;
alter table inspection_templates    enable row level security;
alter table template_revisions      enable row level security;
alter table inspection_requirements enable row level security;
alter table projects                enable row level security;
alter table works_orders            enable row level security;
alter table inspections             enable row level security;
alter table inspection_results      enable row level security;
alter table attachments             enable row level security;
alter table failed_checks           enable row level security;
alter table audit_trail             enable row level security;

-- Reference data: everyone signed in reads, administrators write.
do $$
declare t text;
begin
  foreach t in array array['division_profile','departments','manufacturing_stages',
                           'product_families','defect_codes','equipment','projects','works_orders']
  loop
    execute format('create policy %I_read on %I for select using (auth.uid() is not null)', t||'_r', t);
    execute format($p$create policy %I on %I for all
                       using (has_role('quality_manager','sysadmin'))
                       with check (has_role('quality_manager','sysadmin'))$p$, t||'_w', t);
  end loop;
end $$;

-- Profiles: read yourself; managers read everyone; only admins write.
create policy profiles_self on profiles for select
  using (id = auth.uid() or has_role('quality_manager','quality_engineer','planner','sysadmin'));
create policy profiles_admin on profiles for all
  using (has_role('sysadmin','quality_manager'))
  with check (has_role('sysadmin','quality_manager'));

create policy competencies_read on competencies for select using (auth.uid() is not null);
create policy competencies_write on competencies for all
  using (has_role('quality_manager','sysadmin'))
  with check (has_role('quality_manager','sysadmin'));

-- Templates: everyone reads published; designers write drafts; publishing is separate.
create policy templates_read on inspection_templates for select using (auth.uid() is not null);
create policy templates_write on inspection_templates for all
  using (has_role('quality_engineer','quality_manager','sysadmin'))
  with check (has_role('quality_engineer','quality_manager','sysadmin'));

create policy revs_read on template_revisions for select using (auth.uid() is not null);
create policy revs_draft on template_revisions for insert
  with check (has_role('quality_engineer','quality_manager','sysadmin')
              and status = 'draft' and created_by = auth.uid());
create policy revs_edit on template_revisions for update
  using (status in ('draft','in_review')
         and (created_by = auth.uid() or has_role('quality_manager')))
  with check (true);
-- publishing is a manager action and cannot be self-approval
create policy revs_publish on template_revisions for update
  using (has_role('quality_manager') and created_by <> auth.uid());

-- Requirements matrix: everyone reads, quality manager and admin configure.
create policy req_read on inspection_requirements for select using (auth.uid() is not null);
create policy req_write on inspection_requirements for all
  using (has_role('quality_manager','sysadmin'))
  with check (has_role('quality_manager','sysadmin'));

-- Inspections: inspectors see their own and their department's;
-- quality, planners and admins see all.
create policy insp_read on inspections for select using (
  assigned_to = auth.uid()
  or department_id = my_department()
  or has_role('quality_engineer','quality_manager','planner','sysadmin','readonly')
);
create policy insp_create on inspections for insert
  with check (has_role('planner','quality_engineer','quality_manager','sysadmin'));
create policy insp_update on inspections for update using (
  (assigned_to = auth.uid() and status in ('scheduled','in_progress'))
  or has_role('quality_engineer','quality_manager','planner','sysadmin')
);

create policy res_read on inspection_results for select using (
  exists (select 1 from inspections i where i.id = inspection_id
          and (i.assigned_to = auth.uid() or i.department_id = my_department()
               or has_role('quality_engineer','quality_manager','planner','sysadmin','readonly')))
);
create policy res_write on inspection_results for all using (
  exists (select 1 from inspections i where i.id = inspection_id
          and i.assigned_to = auth.uid() and i.signed_at is null)
) with check (
  exists (select 1 from inspections i where i.id = inspection_id
          and i.assigned_to = auth.uid() and i.signed_at is null)
);

create policy att_read on attachments for select using (auth.uid() is not null);
create policy att_write on attachments for insert with check (uploaded_by = auth.uid());

create policy fc_read on failed_checks for select using (auth.uid() is not null);
create policy fc_write on failed_checks for insert
  with check (has_role('inspector','supervisor','quality_engineer','quality_manager','sysadmin'));
-- disposition is a supervisor decision, and never by the person who recorded it
create policy fc_disposition on failed_checks for update using (
  has_role('supervisor','quality_engineer','quality_manager')
) with check (true);

-- Audit trail: read for quality and admin, insert by trigger only, never update or delete.
create policy audit_read on audit_trail for select
  using (has_role('quality_manager','quality_engineer','sysadmin','readonly'));
revoke update, delete on audit_trail from anon, authenticated;
revoke delete on inspections from anon, authenticated;
revoke delete on inspection_results from anon, authenticated;

-- ------------------------------------------------------------
-- Views the app reads for dashboards (always in step with the data).
--
-- security_invoker = on is not optional. A Postgres view runs as its
-- OWNER by default, which means it bypasses row level security and
-- would hand every row to any signed-in user. With invoker security the
-- view is evaluated as the caller and the policies above still apply.
-- ------------------------------------------------------------
create or replace view v_stage_yield with (security_invoker = on) as
select s.name as stage,
       count(*)                                              as inspections,
       count(*) filter (where i.result = 'pass')             as passed,
       round(100.0 * count(*) filter (where i.result = 'pass')
             / nullif(count(*),0), 1)                        as pass_rate
from inspections i
join manufacturing_stages s on s.id = i.stage_id
where i.status = 'completed'
  and i.completed_at > now() - interval '30 days'
group by s.name, s.id
order by min(s.sort_order);

create or replace view v_open_work with (security_invoker = on) as
select i.*, s.name as stage_name, p.full_name as inspector
from inspections i
join manufacturing_stages s on s.id = i.stage_id
left join profiles p on p.id = i.assigned_to
where i.status in ('scheduled','in_progress');


-- ============================================================
--  SECTION 2 — 002-app-wiring.sql
-- ============================================================

-- ------------------------------------------------------------
-- 1. A new Entra sign-in creates an inactive profile automatically.
--    Authenticating is not access: an administrator activates the user
--    and assigns a role before they can see or do anything.
-- ------------------------------------------------------------
create or replace function handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into profiles (id, entra_oid, full_name, email, role, active)
  values (
    new.id,
    new.raw_user_meta_data->>'provider_id',
    coalesce(new.raw_user_meta_data->>'full_name',
             new.raw_user_meta_data->>'name',
             split_part(new.email, '@', 1)),
    new.email,
    'inspector',
    false
  )
  on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_user();

-- ------------------------------------------------------------
-- 2. Reference numbers are assigned by the database, never the browser.
--    Two inspectors submitting at the same moment cannot collide.
-- ------------------------------------------------------------
create or replace function set_inspection_ref()
returns trigger language plpgsql as $$
begin
  if new.ref is null or new.ref = '' then new.ref := next_ref('INS'); end if;
  return new;
end $$;
create trigger trg_inspection_ref before insert on inspections
  for each row execute function set_inspection_ref();

create or replace function set_failed_check_ref()
returns trigger language plpgsql as $$
begin
  if new.ref is null or new.ref = '' then new.ref := next_ref('FC'); end if;
  return new;
end $$;
create trigger trg_fc_ref before insert on failed_checks
  for each row execute function set_failed_check_ref();

-- ------------------------------------------------------------
-- 3. Photo storage. Private bucket; access follows the inspection.
-- ------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('inspection-photos', 'inspection-photos', false, 8388608,
        array['image/jpeg','image/png','image/webp'])
on conflict (id) do nothing;

create policy "qgrid read own division photos" on storage.objects for select
  using (bucket_id = 'inspection-photos' and auth.uid() is not null);

create policy "qgrid upload photos" on storage.objects for insert
  with check (bucket_id = 'inspection-photos'
              and auth.uid() is not null
              and (storage.foldername(name))[1] = 'inspections');

-- Photos are evidence. Nobody deletes them from the client.
create policy "qgrid no photo deletes" on storage.objects for delete
  using (false);

-- ------------------------------------------------------------
-- 4. Publishing a template revision.
--    Enforces the second-approver rule and supersedes the previous
--    revision in one transaction, so there is never a moment with two
--    published revisions or none.
-- ------------------------------------------------------------
create or replace function publish_template_revision(p_rev uuid)
returns jsonb language plpgsql security invoker as $$
declare v_tpl uuid; v_author uuid; v_rev smallint;
begin
  if not has_role('quality_manager') then
    raise exception 'PUBLISH_ROLE: only a Quality Manager may publish a template';
  end if;

  select template_id, created_by, rev into v_tpl, v_author, v_rev
    from template_revisions where id = p_rev;
  if v_tpl is null then raise exception 'PUBLISH_MISSING: revision not found'; end if;

  if v_author = auth.uid() then
    raise exception 'PUBLISH_SELF: a template cannot be published by the person who built it';
  end if;

  update template_revisions
     set status = 'superseded'
   where template_id = v_tpl and status = 'published';

  update template_revisions
     set status = 'published',
         approved_by = auth.uid(),
         effective_from = current_date
   where id = p_rev;

  return jsonb_build_object('template_id', v_tpl, 'rev', v_rev, 'status', 'published');
end $$;

-- ------------------------------------------------------------
-- 5. Submitting an inspection.
--    One transaction: score the results, raise a failed check for every
--    failure, then sign. Doing this client-side would leave half-signed
--    inspections behind whenever the shop floor Wi-Fi drops mid-submit.
-- ------------------------------------------------------------
create or replace function submit_inspection(p_inspection uuid, p_signature text)
returns jsonb language plpgsql security invoker as $$
declare
  v_insp   inspections;
  v_def    jsonb;
  v_fails  int := 0;
  v_hold   boolean := false;
  v_hp     boolean;
  r        record;
  v_field  jsonb;
begin
  select * into v_insp from inspections where id = p_inspection;
  if v_insp.id is null then raise exception 'SUBMIT_MISSING: inspection not found'; end if;
  if v_insp.signed_at is not null then
    raise exception 'INS_SIGNED: % is already signed', v_insp.ref;
  end if;
  if v_insp.assigned_to <> auth.uid() and not has_role('quality_engineer','quality_manager') then
    raise exception 'SUBMIT_OWNER: this inspection is assigned to someone else';
  end if;

  select hold_points into v_hp from division_profile where id;
  select definition into v_def from template_revisions where id = v_insp.template_rev_id;

  -- Every field the template marks required must have an answer.
  for v_field in
    select f from jsonb_array_elements(v_def->'sections') s,
                   jsonb_array_elements(s->'items') f
     where (f->>'req')::boolean is true
       and coalesce(f->>'type','') not in ('info','section','sign')
  loop
    if not exists (
      select 1 from inspection_results
       where inspection_id = p_inspection
         and field_id = v_field->>'id'
         and (outcome is not null or value_text is not null or value_num is not null)
    ) then
      raise exception 'SUBMIT_INCOMPLETE: % has not been answered', v_field->>'label';
    end if;
  end loop;

  -- Raise a failed check for each failure, carrying the template's
  -- default defect code and hold-point flag.
  for r in
    select ir.id as result_id, ir.field_id, f as field
      from inspection_results ir
      join jsonb_array_elements(v_def->'sections') s on true
      join jsonb_array_elements(s->'items') f on f->>'id' = ir.field_id
     where ir.inspection_id = p_inspection and ir.outcome = 'fail'
  loop
    v_fails := v_fails + 1;
    if v_hp and (r.field->>'hold')::boolean is true then v_hold := true; end if;

    insert into failed_checks (inspection_id, result_id, defect_code_id, is_hold, disposition)
    select p_inspection, r.result_id,
           (select id from defect_codes where code = r.field->>'dfc'),
           v_hp and (r.field->>'hold')::boolean is true,
           'awaiting';
  end loop;

  update inspections
     set status = 'completed',
         result = case when v_fails > 0 then 'fail' else 'pass' end,
         completed_at = now(),
         signed_by = auth.uid(),
         signed_at = now(),
         signature_hash = md5(coalesce(p_signature,'') || p_inspection::text || now()::text)
   where id = p_inspection;

  -- Hold points, when the division uses them, stop the works order.
  if v_hold and v_insp.works_order_id is not null then
    update works_orders set status = 'held' where id = v_insp.works_order_id;
  end if;

  return jsonb_build_object(
    'ref', v_insp.ref,
    'result', case when v_fails > 0 then 'fail' else 'pass' end,
    'failed_checks', v_fails,
    'works_order_held', v_hold);
end $$;

-- ------------------------------------------------------------
-- 6. Generating the schedule from the requirements matrix.
--    Releasing a works order creates every inspection that product
--    family requires, so nothing depends on someone remembering.
-- ------------------------------------------------------------
create or replace function generate_inspections(p_works_order int)
returns jsonb language plpgsql security invoker as $$
declare
  v_wo works_orders; v_family smallint; v_made int := 0; r record; i int;
begin
  if not has_role('planner','quality_engineer','quality_manager','sysadmin') then
    raise exception 'GEN_ROLE: you may not generate a schedule';
  end if;

  select * into v_wo from works_orders where id = p_works_order;
  if v_wo.id is null then raise exception 'GEN_MISSING: works order not found'; end if;
  select family_id into v_family from projects where id = v_wo.project_id;

  for r in
    select req.*, tr.id as rev_id, d.id as dept_id
      from inspection_requirements req
      join template_revisions tr
        on tr.template_id = req.template_id and tr.status = 'published'
      left join departments d on d.stage_id = req.stage_id
     where req.family_id = v_family
       and req.level <> 'na'
       and req.template_id is not null
  loop
    -- 100% inspection means one per unit; every other rule means one per order.
    for i in 1 .. case when r.sampling = 'full' then v_wo.qty else 1 end loop
      insert into inspections
        (template_rev_id, stage_id, project_id, works_order_id, unit_ref,
         department_id, planned_date, status, generated_from)
      values
        (r.rev_id, r.stage_id, v_wo.project_id, p_works_order,
         case when r.sampling = 'full' then v_wo.code || '/' || i else v_wo.code end,
         r.dept_id, current_date, 'scheduled', 'works_order');
      v_made := v_made + 1;
    end loop;
  end loop;

  update works_orders set released_at = coalesce(released_at, now()) where id = p_works_order;
  return jsonb_build_object('works_order', v_wo.code, 'created', v_made);
end $$;

-- ------------------------------------------------------------
-- 7. Dashboard figures. A view, so they can never drift from the records.
--    security_invoker = on so the counts respect row level security:
--    an inspector sees their department's numbers, Quality sees all.
-- ------------------------------------------------------------
create or replace view v_dashboard with (security_invoker = on) as
select
  (select count(*) from inspections where status in ('scheduled','in_progress'))            as open_inspections,
  (select count(*) from inspections
    where status = 'scheduled' and planned_date < current_date)                             as overdue,
  (select count(*) from inspections where assigned_to is null and status = 'scheduled')     as unassigned,
  (select count(*) from failed_checks where disposition = 'awaiting')                       as awaiting_disposition,
  (select count(*) from inspections
    where status = 'completed' and completed_at > now() - interval '30 days')               as completed_30d,
  (select round(100.0 * count(*) filter (where result = 'pass') / nullif(count(*),0), 1)
     from inspections
    where status = 'completed' and completed_at > now() - interval '30 days')               as pass_rate_30d;

grant select on v_dashboard, v_stage_yield, v_open_work to authenticated;
-- Argument lists stated: a grant on a bare function name breaks the
-- moment that function gains an overload, and the error names the
-- grant rather than the overload that caused it.
grant execute on function publish_template_revision(uuid), submit_inspection(uuid, text), generate_inspections(bigint, date) to authenticated;


-- ============================================================
--  SECTION 3 — 003-publish-roles.sql
-- ============================================================

create or replace function publish_template_revision(p_rev uuid)
returns jsonb language plpgsql security invoker as $$
declare v_tpl uuid; v_author uuid; v_rev smallint;
begin
  if not has_role('quality_manager', 'sysadmin') then
    raise exception 'PUBLISH_ROLE: only a Quality Manager or System Administrator may publish a template';
  end if;

  select template_id, created_by, rev into v_tpl, v_author, v_rev
    from template_revisions where id = p_rev;
  if v_tpl is null then raise exception 'PUBLISH_MISSING: revision not found'; end if;

  if v_author = auth.uid() then
    raise exception 'PUBLISH_SELF: a template cannot be published by the person who built it. Ask a second Quality Manager to approve it.';
  end if;

  update template_revisions
     set status = 'superseded'
   where template_id = v_tpl and status = 'published';

  update template_revisions
     set status = 'published',
         approved_by = auth.uid(),
         effective_from = current_date
   where id = p_rev;

  return jsonb_build_object('template_id', v_tpl, 'rev', v_rev, 'status', 'published');
end $$;

-- Argument lists stated: a grant on a bare function name breaks the
-- moment that function gains an overload, and the error names the
-- grant rather than the overload that caused it.
grant execute on function publish_template_revision(uuid) to authenticated;


-- ============================================================
--  SECTION 4 — 004-publish-approval-optional.sql
-- ============================================================

-- 1. The setting.
alter table division_profile
  add column if not exists require_second_approver boolean not null default false;

comment on column division_profile.require_second_approver is
  'When true, the author of a template revision cannot publish it. Off by '
  'default: a division with a single Quality Manager would otherwise be '
  'unable to publish anything.';

-- 2. The constraint has to go: it enforced the rule unconditionally, so it
--    would override the setting. The rule now lives in the function, which
--    can read the setting.
alter table template_revisions drop constraint if exists approver_not_author;

-- 3. The function.
create or replace function publish_template_revision(p_rev uuid)
returns jsonb language plpgsql security invoker as $$
declare
  v_tpl uuid; v_author uuid; v_rev smallint; v_require boolean;
begin
  if not has_role('quality_manager', 'sysadmin') then
    raise exception 'PUBLISH_ROLE: only a Quality Manager or System Administrator may publish a template';
  end if;

  select template_id, created_by, rev into v_tpl, v_author, v_rev
    from template_revisions where id = p_rev;
  if v_tpl is null then raise exception 'PUBLISH_MISSING: revision not found'; end if;

  select require_second_approver into v_require from division_profile where id;

  if coalesce(v_require, false) and v_author = auth.uid() then
    raise exception 'PUBLISH_SELF: this division requires a second approver, so the person who built a template cannot publish it.';
  end if;

  update template_revisions
     set status = 'superseded'
   where template_id = v_tpl and status = 'published';

  update template_revisions
     set status = 'published',
         approved_by = auth.uid(),
         effective_from = current_date
   where id = p_rev;

  return jsonb_build_object('template_id', v_tpl, 'rev', v_rev, 'status', 'published',
                            'self_approved', v_author = auth.uid());
end $$;

-- Argument lists stated: a grant on a bare function name breaks the
-- moment that function gains an overload, and the error names the
-- grant rather than the overload that caused it.
grant execute on function publish_template_revision(uuid) to authenticated;


-- ============================================================
--  SECTION 5 — 005-lock-ref-sequences.sql
-- ============================================================

-- 1. The function does the privileged work, with a pinned search_path so a
--    caller cannot shadow the table it writes to.
create or replace function next_ref(p_prefix text, p_width int default 4)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare v_period text; v_next int;
begin
  v_period := to_char(now(), 'YY');
  perform pg_advisory_xact_lock(hashtext(p_prefix));
  insert into ref_sequences (prefix, period, last_val)
    values (p_prefix, v_period, 0)
    on conflict (prefix) do nothing;
  update ref_sequences
     set last_val = case when period = v_period then last_val + 1 else 1 end,
         period   = v_period
   where prefix = p_prefix
  returning last_val into v_next;
  return p_prefix || '-' || v_period || '-' || lpad(v_next::text, p_width, '0');
end $$;

-- 2. The table is closed. RLS on with no policies denies every client
--    request; the revoke removes the default grants as well, so both
--    layers say no.
alter table ref_sequences enable row level security;
revoke all on ref_sequences from anon, authenticated;

comment on table ref_sequences is
  'Reference number counters. No client access at all: read and written only '
  'by next_ref(), which is SECURITY DEFINER. Rewinding a counter would issue '
  'a reference number that already belongs to a signed record.';

-- 3. next_ref is called from BEFORE INSERT triggers on inspections and
--    failed_checks, so authenticated must still be able to execute it.
grant execute on function next_ref(text, int) to authenticated;

-- ------------------------------------------------------------
--  The migration ledger, same treatment.
--
--  public.qgrid_migrations records which numbered files have been applied.
--  It is created by scripts/migrate.mjs and by schema-complete.sql rather
--  than by a migration, so it had escaped the RLS sweep entirely. A
--  signed-in user could delete a row from it and the next migration run
--  would re-apply that file — against a database that already has it.
--
--  Created here too, idempotently, so the lockdown travels with the
--  schema rather than depending on which route was used to build it.
-- ------------------------------------------------------------
create table if not exists public.qgrid_migrations (
  filename   text primary key,
  applied_at timestamptz not null default now()
);

alter table public.qgrid_migrations enable row level security;
revoke all on public.qgrid_migrations from anon, authenticated;

comment on table public.qgrid_migrations is
  'Which numbered migrations have been applied. No client access: read and '
  'written only by scripts/migrate.mjs over a service-role connection.';


-- ============================================================
--  SECTION 6 — 006-fix-silent-publish.sql
-- ============================================================

-- ------------------------------------------------------------
-- 1. Policies. Replaced wholesale so the set is readable in one place
--    rather than accumulating exceptions.
-- ------------------------------------------------------------
drop policy if exists revs_edit on template_revisions;
drop policy if exists revs_publish on template_revisions;

-- Editing a draft: its author, a Quality Manager, or an administrator.
create policy revs_edit on template_revisions for update
  using (
    status in ('draft', 'in_review')
    and (created_by = auth.uid() or has_role('quality_manager', 'sysadmin'))
  )
  with check (true);

-- Publishing and superseding: Quality Manager or administrator. Whether the
-- author may approve their own work is decided by the division setting inside
-- publish_template_revision, not here — a policy cannot read that setting
-- cleanly, and having the rule in two places is how they drift apart.
create policy revs_publish on template_revisions for update
  using (has_role('quality_manager', 'sysadmin'))
  with check (true);

-- ------------------------------------------------------------
-- 2. The function asserts that its updates actually landed.
-- ------------------------------------------------------------
create or replace function publish_template_revision(p_rev uuid)
returns jsonb language plpgsql security invoker as $$
declare
  v_tpl uuid; v_author uuid; v_rev smallint; v_require boolean; v_rows int;
begin
  if not has_role('quality_manager', 'sysadmin') then
    raise exception 'PUBLISH_ROLE: only a Quality Manager or System Administrator may publish a template';
  end if;

  select template_id, created_by, rev into v_tpl, v_author, v_rev
    from template_revisions where id = p_rev;
  if v_tpl is null then raise exception 'PUBLISH_MISSING: revision not found'; end if;

  select require_second_approver into v_require from division_profile where id;

  if coalesce(v_require, false) and v_author = auth.uid() then
    raise exception 'PUBLISH_SELF: this division requires a second approver, so the person who built a template cannot publish it.';
  end if;

  update template_revisions
     set status = 'superseded'
   where template_id = v_tpl and status = 'published';

  update template_revisions
     set status = 'published',
         approved_by = auth.uid(),
         effective_from = current_date
   where id = p_rev;

  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    -- The row exists: it was read at the top of this function. So the update
    -- was filtered by row level security, not missing.
    raise exception 'PUBLISH_BLOCKED: row level security prevented the update. Your role may not edit this revision.';
  end if;

  return jsonb_build_object('template_id', v_tpl, 'rev', v_rev, 'status', 'published',
                            'self_approved', v_author = auth.uid());
end $$;

-- ------------------------------------------------------------
-- 3. The same assertion on submitting an inspection, which has exactly
--    the same shape: a final UPDATE that RLS could filter, after which
--    the function would report a signed inspection that is not signed.
-- ------------------------------------------------------------
create or replace function submit_inspection(p_inspection uuid, p_signature text)
returns jsonb language plpgsql security invoker as $$
declare
  v_insp inspections; v_def jsonb; v_fails int := 0; v_hold boolean := false;
  v_hp boolean; r record; v_field jsonb; v_rows int;
begin
  select * into v_insp from inspections where id = p_inspection;
  if v_insp.id is null then raise exception 'SUBMIT_MISSING: inspection not found'; end if;
  if v_insp.signed_at is not null then
    raise exception 'INS_SIGNED: % is already signed', v_insp.ref;
  end if;
  if v_insp.assigned_to <> auth.uid() and not has_role('quality_engineer','quality_manager') then
    raise exception 'SUBMIT_OWNER: this inspection is assigned to someone else';
  end if;

  select hold_points into v_hp from division_profile where id;
  select definition into v_def from template_revisions where id = v_insp.template_rev_id;

  for v_field in
    select f from jsonb_array_elements(v_def->'sections') s,
                   jsonb_array_elements(s->'items') f
     where (f->>'req')::boolean is true
       and coalesce(f->>'type','') not in ('info','section','sign')
  loop
    if not exists (
      select 1 from inspection_results
       where inspection_id = p_inspection
         and field_id = v_field->>'id'
         and (outcome is not null or value_text is not null or value_num is not null)
    ) then
      raise exception 'SUBMIT_INCOMPLETE: % has not been answered', v_field->>'label';
    end if;
  end loop;

  for r in
    select ir.id as result_id, ir.field_id, f as field
      from inspection_results ir
      join jsonb_array_elements(v_def->'sections') s on true
      join jsonb_array_elements(s->'items') f on f->>'id' = ir.field_id
     where ir.inspection_id = p_inspection and ir.outcome = 'fail'
  loop
    v_fails := v_fails + 1;
    if v_hp and (r.field->>'hold')::boolean is true then v_hold := true; end if;
    insert into failed_checks (inspection_id, result_id, defect_code_id, is_hold, disposition)
    select p_inspection, r.result_id,
           (select id from defect_codes where code = r.field->>'dfc'),
           v_hp and (r.field->>'hold')::boolean is true,
           'awaiting';
  end loop;

  update inspections
     set status = 'completed',
         result = case when v_fails > 0 then 'fail' else 'pass' end,
         completed_at = now(),
         signed_by = auth.uid(),
         signed_at = now(),
         signature_hash = md5(coalesce(p_signature,'') || p_inspection::text || now()::text)
   where id = p_inspection;

  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception 'SUBMIT_BLOCKED: row level security prevented the record from being signed.';
  end if;

  if v_hold and v_insp.works_order_id is not null then
    update works_orders set status = 'held' where id = v_insp.works_order_id;
  end if;

  return jsonb_build_object(
    'ref', v_insp.ref,
    'result', case when v_fails > 0 then 'fail' else 'pass' end,
    'failed_checks', v_fails,
    'works_order_held', v_hold);
end $$;

-- Argument lists stated: a grant on a bare function name breaks the
-- moment that function gains an overload, and the error names the
-- grant rather than the overload that caused it.
grant execute on function publish_template_revision(uuid), submit_inspection(uuid, text) to authenticated;


-- ============================================================
--  SECTION 7 — 007-no-empty-templates.sql
-- ============================================================

-- ------------------------------------------------------------
--  PREREQUISITES. Run migrations in order.
--
--  Without this, a missing earlier migration shows up as a raw error
--  about a column that does not exist, several statements in, with
--  nothing saying which file to run first.
-- ------------------------------------------------------------
do $prereq$
begin
  if not exists (select 1 from information_schema.columns
                where table_name = 'division_profile' and column_name = 'require_second_approver') then
    raise exception '007 needs 004-publish-approval-optional.sql first.';
  end if;
end $prereq$;


create or replace function publish_template_revision(p_rev uuid)
returns jsonb language plpgsql security invoker as $$
declare
  v_tpl uuid; v_author uuid; v_rev smallint; v_require boolean;
  v_rows int; v_fields int; v_def jsonb;
begin
  if not has_role('quality_manager', 'sysadmin') then
    raise exception 'PUBLISH_ROLE: only a Quality Manager or System Administrator may publish a template';
  end if;

  select template_id, created_by, rev, definition
    into v_tpl, v_author, v_rev, v_def
    from template_revisions where id = p_rev;
  if v_tpl is null then raise exception 'PUBLISH_MISSING: revision not found'; end if;

  -- Something an inspector can actually answer. Headings and instructions
  -- are not questions.
  select count(*) into v_fields
    from jsonb_array_elements(coalesce(v_def->'sections', '[]'::jsonb)) s,
         jsonb_array_elements(coalesce(s->'items', '[]'::jsonb)) f
   where coalesce(f->>'type', '') not in ('section', 'info');

  if v_fields = 0 then
    raise exception 'PUBLISH_EMPTY: this revision has no questions on it, so an inspection generated from it could not be completed.';
  end if;

  select require_second_approver into v_require from division_profile where id;

  if coalesce(v_require, false) and v_author = auth.uid() then
    raise exception 'PUBLISH_SELF: this division requires a second approver, so the person who built a template cannot publish it.';
  end if;

  update template_revisions
     set status = 'superseded'
   where template_id = v_tpl and status = 'published';

  update template_revisions
     set status = 'published',
         approved_by = auth.uid(),
         effective_from = current_date
   where id = p_rev;

  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception 'PUBLISH_BLOCKED: row level security prevented the update. Your role may not edit this revision.';
  end if;

  return jsonb_build_object('template_id', v_tpl, 'rev', v_rev, 'status', 'published',
                            'fields', v_fields, 'self_approved', v_author = auth.uid());
end $$;

-- Argument lists stated: a grant on a bare function name breaks the
-- moment that function gains an overload, and the error names the
-- grant rather than the overload that caused it.
grant execute on function publish_template_revision(uuid) to authenticated;


-- ============================================================
--  SECTION 8 — 008-fault-list.sql
-- ============================================================

-- ------------------------------------------------------------
--  PREREQUISITES. Run migrations in order.
--
--  Without this, a missing earlier migration shows up as a raw error
--  about a column that does not exist, several statements in, with
--  nothing saying which file to run first.
-- ------------------------------------------------------------
do $prereq$
begin
  if not exists (select 1 from information_schema.columns
                where table_name = 'division_profile' and column_name = 'require_second_approver') then
    raise exception '008 needs 004-publish-approval-optional.sql first.';
  end if;
end $prereq$;


-- result_id is only meaningful for a defect found AT a checkpoint. A fault
-- typed into a fault list is not attached to one.
alter table failed_checks alter column result_id drop not null;

alter table failed_checks
  add column if not exists source text not null default 'checkpoint'
    check (source in ('checkpoint', 'fault_list')),
  add column if not exists field_id    text,      -- which fault list it came from
  add column if not exists seq         smallint,  -- line number as the inspector sees it
  add column if not exists description text,
  add column if not exists location    text,      -- where on the panel
  add column if not exists severity    text check (severity in ('minor', 'major')),
  add column if not exists qty         smallint not null default 1;

comment on column failed_checks.source is
  'checkpoint: a checklist question failed. fault_list: typed into a fault '
  'list on the form. Both are defects and both become NCRs in Phase 2.';

-- A defect found at a checkpoint must still name the checkpoint; one typed
-- into a fault list must say what it is. Neither rule can be expressed by a
-- NOT NULL now that both kinds share the table.
alter table failed_checks drop constraint if exists failed_checks_shape;
alter table failed_checks add constraint failed_checks_shape check (
  (source = 'checkpoint' and result_id is not null)
  or
  (source = 'fault_list' and field_id is not null
   and description is not null and length(btrim(description)) > 0)
);

create index if not exists failed_checks_inspection_idx
  on failed_checks (inspection_id, source, seq);

-- ------------------------------------------------------------
--  Counting defects. One query over both kinds, which was the whole
--  point of not adding a second table.
-- ------------------------------------------------------------
create or replace view v_defect_pareto with (security_invoker = on) as
select d.code,
       d.description                      as defect,
       count(*)                           as occurrences,
       sum(f.qty)                         as units_affected,
       count(*) filter (where f.source = 'fault_list')  as from_fault_lists,
       count(*) filter (where f.source = 'checkpoint')  as from_checkpoints,
       count(*) filter (where f.disposition = 'awaiting') as awaiting
  from failed_checks f
  join defect_codes d on d.id = f.defect_code_id
 group by d.code, d.description
 order by count(*) desc;

grant select on v_defect_pareto to authenticated;

-- ------------------------------------------------------------
--  Submitting an inspection must not lose the fault list.
--
--  submit_inspection raises a failed check per failed checkpoint. Faults
--  are written as the inspector types them, so they already exist — but
--  the inspection's overall result has to account for them, or a panel
--  with five faults and no failed checkpoint would submit as a pass.
-- ------------------------------------------------------------
create or replace function submit_inspection(p_inspection uuid, p_signature text)
returns jsonb language plpgsql security invoker as $$
declare
  v_insp inspections; v_def jsonb; v_fails int := 0; v_faults int := 0;
  v_hold boolean := false; v_hp boolean; r record; v_field jsonb; v_rows int;
begin
  select * into v_insp from inspections where id = p_inspection;
  if v_insp.id is null then raise exception 'SUBMIT_MISSING: inspection not found'; end if;
  if v_insp.signed_at is not null then
    raise exception 'INS_SIGNED: % is already signed', v_insp.ref;
  end if;
  if v_insp.assigned_to <> auth.uid() and not has_role('quality_engineer','quality_manager') then
    raise exception 'SUBMIT_OWNER: this inspection is assigned to someone else';
  end if;

  select hold_points into v_hp from division_profile where id;
  select definition into v_def from template_revisions where id = v_insp.template_rev_id;

  -- Required fields must be answered. A fault list answers itself: the
  -- inspector either listed faults or confirmed there were none, and both
  -- write a result row.
  for v_field in
    select f from jsonb_array_elements(v_def->'sections') s,
                   jsonb_array_elements(s->'items') f
     where (f->>'req')::boolean is true
       and coalesce(f->>'type','') not in ('info','section','sign')
  loop
    if not exists (
      select 1 from inspection_results
       where inspection_id = p_inspection
         and field_id = v_field->>'id'
         and (outcome is not null or value_text is not null or value_num is not null)
    ) then
      raise exception 'SUBMIT_INCOMPLETE: % has not been answered', v_field->>'label';
    end if;
  end loop;

  for r in
    select ir.id as result_id, ir.field_id, f as field
      from inspection_results ir
      join jsonb_array_elements(v_def->'sections') s on true
      join jsonb_array_elements(s->'items') f on f->>'id' = ir.field_id
     where ir.inspection_id = p_inspection and ir.outcome = 'fail'
  loop
    v_fails := v_fails + 1;
    if v_hp and (r.field->>'hold')::boolean is true then v_hold := true; end if;
    insert into failed_checks (inspection_id, result_id, defect_code_id, is_hold,
                               disposition, source)
    select p_inspection, r.result_id,
           (select id from defect_codes where code = r.field->>'dfc'),
           v_hp and (r.field->>'hold')::boolean is true,
           'awaiting', 'checkpoint';
  end loop;

  -- Faults recorded on a fault list count towards the result.
  select count(*) into v_faults
    from failed_checks
   where inspection_id = p_inspection and source = 'fault_list';

  update inspections
     set status = 'completed',
         result = case when v_fails + v_faults > 0 then 'fail' else 'pass' end,
         completed_at = now(),
         signed_by = auth.uid(),
         signed_at = now(),
         signature_hash = md5(coalesce(p_signature,'') || p_inspection::text || now()::text)
   where id = p_inspection;

  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception 'SUBMIT_BLOCKED: row level security prevented the record from being signed.';
  end if;

  if v_hold and v_insp.works_order_id is not null then
    update works_orders set status = 'held' where id = v_insp.works_order_id;
  end if;

  return jsonb_build_object(
    'ref', v_insp.ref,
    'result', case when v_fails + v_faults > 0 then 'fail' else 'pass' end,
    'failed_checks', v_fails,
    'faults', v_faults,
    'works_order_held', v_hold);
end $$;

-- Argument lists stated: a grant on a bare function name breaks the
-- moment that function gains an overload, and the error names the
-- grant rather than the overload that caused it.
grant execute on function submit_inspection(uuid, text) to authenticated;


-- ============================================================
--  SECTION 9 — 009-photo-storage.sql
-- ============================================================

-- 1. Detaching a photo from an inspection.
drop policy if exists att_detach on attachments;
create policy att_detach on attachments for delete
  using (
    uploaded_by = auth.uid()
    or has_role('quality_engineer', 'quality_manager', 'sysadmin')
  );

comment on table attachments is
  'Links a stored object to an inspection. Deleting a row DETACHES the photo; '
  'the object in storage is never removed, because it is evidence.';

-- 2. The bucket, idempotently.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('inspection-photos', 'inspection-photos', false, 8388608,
        array['image/jpeg','image/png','image/webp'])
on conflict (id) do update
  set public = false,
      file_size_limit = 8388608,
      allowed_mime_types = array['image/jpeg','image/png','image/webp'];

-- 3. The policies, replaced so the set is current rather than accumulated.
drop policy if exists "qgrid read own division photos" on storage.objects;
drop policy if exists "qgrid upload photos" on storage.objects;
drop policy if exists "qgrid no photo deletes" on storage.objects;
drop policy if exists "q360 read own division photos" on storage.objects;
drop policy if exists "q360 upload photos" on storage.objects;
drop policy if exists "q360 no photo deletes" on storage.objects;

-- TO AUTHENTICATED, stated explicitly.
--
-- The originals omitted the role and so applied to PUBLIC. That is usually
-- harmless, but it is not what was meant, and an unqualified policy on a
-- table Supabase also ships its own policies for is hard to reason about
-- when an upload comes back with "new row violates row-level security
-- policy" and no indication of WHICH policy said no.
--
-- The path requirement is also relaxed to two segments. The app writes
-- inspections/<inspection>/<field>/<file>, but insisting on three turned an
-- unexpected path into the same opaque refusal.
create policy "grid read inspection photos" on storage.objects
  for select to authenticated
  using (bucket_id = 'inspection-photos');

create policy "grid upload inspection photos" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'inspection-photos'
    and (storage.foldername(name))[1] = 'inspections'
  );

-- Photos are evidence. Nobody deletes or replaces the object, including an
-- administrator: detaching a photo removes the link, never the file.
create policy "grid never delete inspection photos" on storage.objects
  for delete to authenticated using (false);

create policy "grid never overwrite inspection photos" on storage.objects
  for update to authenticated using (false);

-- ------------------------------------------------------------
--  Check what you have. Run this after the migration: expect exactly the
--  four policies above, and nothing else on this bucket.
-- ------------------------------------------------------------
do $verify$
declare v_count int; v_bucket int;
begin
  select count(*) into v_bucket from storage.buckets where id = 'inspection-photos';
  if v_bucket = 0 then
    raise exception 'The inspection-photos bucket does not exist. The insert above should have created it.';
  end if;

  select count(*) into v_count from pg_policies
   where schemaname = 'storage' and tablename = 'objects'
     and policyname like 'grid %';
  if v_count <> 4 then
    raise exception 'Expected 4 storage policies, found %. Uploads will be refused.', v_count;
  end if;

  raise notice 'Storage ready: bucket present, 4 policies installed.';
end $verify$;


-- ============================================================
--  SECTION 10 — 010-handover.sql
-- ============================================================

-- ------------------------------------------------------------
--  PREREQUISITES. Run migrations in order.
--
--  Without this, a missing earlier migration shows up as a raw error
--  about a column that does not exist, several statements in, with
--  nothing saying which file to run first.
-- ------------------------------------------------------------
do $prereq$
begin
  if not exists (select 1 from information_schema.routines
                where routine_name = 'has_role') then
    raise exception '010 needs 001-init-inspections.sql first.';
  end if;
end $prereq$;


-- Who first opened it. assigned_to moves on a handover; this does not.
alter table inspections
  add column if not exists started_by uuid references profiles(id);

comment on column inspections.started_by is
  'The inspector who first opened the inspection. assigned_to moves on a '
  'handover, signed_by records who finished it. All three can differ.';

create table if not exists inspection_handovers (
  id            uuid primary key default gen_random_uuid(),
  inspection_id uuid not null references inspections(id) on delete cascade,
  from_profile  uuid references profiles(id),
  to_profile    uuid not null references profiles(id),
  handed_by     uuid not null references profiles(id),
  reason        text not null check (length(btrim(reason)) > 0),
  at            timestamptz not null default now()
);
create index if not exists handovers_inspection_idx on inspection_handovers (inspection_id, at);

comment on table inspection_handovers is
  'Why an inspection changed hands. A reason is required: "the record shows '
  'two names" is only defensible if it also shows why.';

alter table inspection_handovers enable row level security;

create policy handover_read on inspection_handovers for select
  using (auth.uid() is not null);

-- Only the roles that can reassign may write one, and the row must say who
-- did it — no anonymous handovers.
create policy handover_write on inspection_handovers for insert
  with check (
    handed_by = auth.uid()
    and has_role('supervisor', 'planner', 'quality_engineer', 'quality_manager', 'sysadmin')
  );

-- A handover is part of the record. It is never edited or removed.
revoke update, delete on inspection_handovers from anon, authenticated;

-- A supervisor can reassign within their own department; the wider roles
-- anywhere. Everything else about insp_update is unchanged.
drop policy if exists insp_update on inspections;
create policy insp_update on inspections for update
  using (
    (assigned_to = auth.uid() and status in ('scheduled', 'in_progress'))
    or has_role('quality_engineer', 'quality_manager', 'planner', 'sysadmin')
    or (has_role('supervisor') and department_id = my_department())
  );

-- ------------------------------------------------------------
--  Reassigning, as one operation.
--
--  Doing it from the browser would be three writes that can half-apply:
--  move the inspection, log the handover, note who started it. This does
--  all three or none, and refuses the cases that should be refused.
-- ------------------------------------------------------------
create or replace function hand_over_inspection(
  p_inspection uuid, p_to uuid, p_reason text)
returns jsonb language plpgsql security invoker as $$
declare v_insp inspections; v_from uuid; v_rows int; v_to_active boolean;
begin
  if not has_role('supervisor', 'planner', 'quality_engineer', 'quality_manager', 'sysadmin') then
    raise exception 'HANDOVER_ROLE: only a supervisor or above can reassign an inspection';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'HANDOVER_REASON: a reason is required';
  end if;

  select * into v_insp from inspections where id = p_inspection;
  if v_insp.id is null then raise exception 'HANDOVER_MISSING: inspection not found'; end if;

  -- A signed inspection is finished. If it is wrong, it needs an amendment,
  -- not a new owner.
  if v_insp.signed_at is not null then
    raise exception 'INS_SIGNED: % is already signed and cannot be reassigned', v_insp.ref;
  end if;

  select active into v_to_active from profiles where id = p_to;
  if v_to_active is not true then
    raise exception 'HANDOVER_TARGET: that person is not an active user';
  end if;
  if v_insp.assigned_to = p_to then
    raise exception 'HANDOVER_SAME: it is already assigned to that person';
  end if;

  v_from := v_insp.assigned_to;

  insert into inspection_handovers (inspection_id, from_profile, to_profile, handed_by, reason)
  values (p_inspection, v_from, p_to, auth.uid(), btrim(p_reason));

  update inspections
     set assigned_to = p_to,
         -- Remember who opened it, the first time it moves.
         started_by = coalesce(started_by, v_from)
   where id = p_inspection;

  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception 'HANDOVER_BLOCKED: row level security prevented the reassignment.';
  end if;

  return jsonb_build_object('ref', v_insp.ref, 'from', v_from, 'to', p_to);
end $$;

-- Argument lists stated: a grant on a bare function name breaks the
-- moment that function gains an overload, and the error names the
-- grant rather than the overload that caused it.
grant execute on function hand_over_inspection(uuid, uuid, text) to authenticated;

-- ------------------------------------------------------------
--  Answers follow the CURRENT assignee.
--
--  Unchanged in substance — the policy already keyed on assigned_to — but
--  restated here so the whole rule is in one migration alongside the
--  handover that makes it move.
-- ------------------------------------------------------------
drop policy if exists res_write on inspection_results;
create policy res_write on inspection_results for all
  using (
    exists (select 1 from inspections i
             where i.id = inspection_id and i.signed_at is null
               and (i.assigned_to = auth.uid()
                    or has_role('quality_engineer', 'quality_manager')))
  )
  with check (
    exists (select 1 from inspections i
             where i.id = inspection_id and i.signed_at is null
               and (i.assigned_to = auth.uid()
                    or has_role('quality_engineer', 'quality_manager')))
  );

-- ------------------------------------------------------------
--  The register needs to show when two names are on one inspection.
-- ------------------------------------------------------------
create or replace view v_inspection_people with (security_invoker = on) as
select i.id,
       i.ref,
       s.full_name as started_by_name,
       a.full_name as assigned_to_name,
       g.full_name as signed_by_name,
       (select count(*) from inspection_handovers h where h.inspection_id = i.id) as handovers
  from inspections i
  left join profiles s on s.id = i.started_by
  left join profiles a on a.id = i.assigned_to
  left join profiles g on g.id = i.signed_by;

grant select on v_inspection_people to authenticated;


-- ============================================================
--  SECTION 11 — 011-fault-clearing.sql
-- ============================================================

-- ------------------------------------------------------------
--  PREREQUISITES. Run migrations in order.
--
--  Without this, a missing earlier migration shows up as a raw error
--  about a column that does not exist, several statements in, with
--  nothing saying which file to run first.
-- ------------------------------------------------------------
do $prereq$
begin
  if not exists (select 1 from information_schema.columns
                where table_name = 'failed_checks' and column_name = 'source') then
    raise exception '011 needs 008-fault-list.sql first (failed_checks.source is missing).';
  end if;
end $prereq$;


alter table failed_checks
  add column if not exists cleared_by   uuid references profiles(id),
  add column if not exists cleared_at   timestamptz,
  add column if not exists verified_by  uuid references profiles(id),
  add column if not exists verified_at  timestamptz;

comment on column failed_checks.cleared_by is
  'Who did the work that put the fault right.';
comment on column failed_checks.verified_by is
  'Who checked the work afterwards. Independent verification is the point, '
  'so the same person doing both is recorded and shown, not silently accepted.';

-- Timestamps written by the database, not sent by the client.
create or replace function stamp_fault_progress()
returns trigger language plpgsql as $$
begin
  if new.cleared_by is distinct from old.cleared_by then
    new.cleared_at := case when new.cleared_by is null then null else now() end;
  end if;
  if new.verified_by is distinct from old.verified_by then
    new.verified_at := case when new.verified_by is null then null else now() end;
  end if;

  -- Verification is a check ON the clearing. Recording it before there is
  -- anything to check is an ordering mistake, not a preference.
  if new.verified_by is not null and new.cleared_by is null then
    raise exception 'FAULT_ORDER: record who cleared the fault before recording who verified it';
  end if;

  return new;
end $$;

drop trigger if exists trg_fault_progress on failed_checks;
create trigger trg_fault_progress
  before update on failed_checks
  for each row execute function stamp_fault_progress();

-- A fault that is cleared and verified is closed. Kept as a view so the
-- Failed checks queue and any later report agree on what "outstanding" means.
create or replace view v_fault_status with (security_invoker = on) as
select f.*,
       c.full_name as cleared_by_name,
       v.full_name as verified_by_name,
       case
         when f.verified_by is not null then 'verified'
         when f.cleared_by  is not null then 'cleared, awaiting verification'
         else 'outstanding'
       end as progress,
       (f.cleared_by is not null and f.cleared_by = f.verified_by) as self_verified
  from failed_checks f
  left join profiles c on c.id = f.cleared_by
  left join profiles v on v.id = f.verified_by;

grant select on v_fault_status to authenticated;

-- Clearing and verifying continue after the inspection is signed, so the
-- update policy cannot be tied to an open inspection.
drop policy if exists fc_progress on failed_checks;
create policy fc_progress on failed_checks for update
  using (
    has_role('inspector', 'supervisor', 'quality_engineer', 'quality_manager', 'sysadmin')
  )
  with check (true);


